class ActivatePlanModal(ConfirmationModal):
    """
    Class for activate plan modal, providing methods to manipulate elements on modal
    """
    _EXECUTE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Execute"]/button'
    _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'
    _DOWNLOAD_PLAN_LABEL_XPATH = '//span[contains(text(), "Download plan without activation")]'
    _DOWNLOAD_PLAN_CHECKBOX_XPATH = ('//span[contains(text(), "Download plan without activation")]'
                                     '/preceding-sibling::input')
    _ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH = ('//span[contains(text(), '
                                                             '"plan despite of validation errors")]')
    _ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_INPUT_XPATH = ('//span[contains(text(), "plan despite of validation '
                                                             'errors")]/preceding-sibling::input')
    _FEEDBACK_TEXT_XPATH = '//div[@class="modal-content"]//div[@class="feedback-section"]/div[2]'

    def wait_until_actiavte_plan_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def close(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)

    def execute(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._EXECUTE_BUTTON_XPATH), timeout)
        if self.check_if_prompt_bts_reset(timeout):
            self.click_enabled_element((By.XPATH, self._EXECUTE_BUTTON_XPATH), timeout)
        return self.check_if_activate_successfully(timeout)

    def select_download_plan_without_activation(self, download_plan_without_activation=False):
        self.select_checkbox_by_specified_status(download_plan_without_activation,
                                                 self._DOWNLOAD_PLAN_CHECKBOX_XPATH,
                                                 self._DOWNLOAD_PLAN_LABEL_XPATH)

    def select_activate_or_download_plan_despite_errors(self, activate_plan_despite_errors=False, timeout=60):
        if self.check_if_exists((By.XPATH, self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH), timeout):
            self.select_checkbox_by_specified_status(activate_plan_despite_errors,
                                                     self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_INPUT_XPATH,
                                                     self._ACTIVATE_OR_DOWNLOAD_PLAN_DESPITE_ERRORS_LABEL_XPATH)

    def check_if_prompt_bts_reset(self, timeout=60):
        return self.check_if_element_has_text((By.XPATH, self._FEEDBACK_TEXT_XPATH), 'BTS reset', timeout)

    def check_if_activate_successfully(self, timeout=60):
        return self.check_if_element_has_text((By.XPATH, self._FEEDBACK_TEXT_XPATH), 'successfully', timeout)


class SaveReportModal(ConfirmationModal):
    _SAVE_REPORT_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Save report"]/button'
    _CLOSE_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Close"]/button'

    def wait_until_save_report_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def close(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._CLOSE_BUTTON_XPATH), timeout)

    def save_report(self, timeout=60):
        start_time = time.time()
        self.click_enabled_element((By.XPATH, self._SAVE_REPORT_BUTTON_XPATH), timeout)
        return self.download_files(start_time)


class SaveBtsConfigurationModal(ConfirmationModal):
    _SAVE_CONFIGURATION_TYPE_MAIN_XPATH = "//div[@class='modal-body']//label[text()='{}']"

    _SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_XPATH = "//div[@class='modal-body']//" \
                                                   "input[contains(@type, 'checkbox')]"
    _SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_FOR_CLICK_XPATH = "//div[@class='modal-body']" \
                                                             "//span[text()='Save also planned parameters changes']"
    _SAVE_CONFIGURATION_MODAL_CLASS = "//ui-modal[@a-title='Save BTS Configuration']"

    def wait_until_save_bts_configuration_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._SAVE_CONFIGURATION_MODAL_CLASS), timeout)

    def save(self, save_configuration_type_str, is_save_planned_parameter_changes_selected):
        save_configuration_button_xpath = "//div[@class='modal-footer']//ui-button[@a-text='Save']/button"
        self._set_save_configuration_type(save_configuration_type_str, is_save_planned_parameter_changes_selected)
        start_time = time.time()
        self.click_enabled_element((By.XPATH, save_configuration_button_xpath))
        return self.download_files(start_time)

    def cancel(self):
        cancel_configuration_button_xpath = "//div[@class='modal-footer']//ui-button[@a-text='Cancel']/button"
        self.click_enabled_element(cancel_configuration_button_xpath)

    def _set_save_configuration_type(self, save_configuration_type_str, is_save_planned_parameter_changes_selected):
        self.click_element_by_xpath(self._SAVE_CONFIGURATION_TYPE_MAIN_XPATH.format(save_configuration_type_str))
        if self.check_if_exists((By.XPATH, self._SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_XPATH)):
            element = self.driver.find_element_by_xpath(self._SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_XPATH)
            if element.is_enabled() and is_save_planned_parameter_changes_selected != element.is_selected():
                self.click_element_by_xpath(self._SAVE_PLANNED_PARAMETERS_CHANGES_CHECK_FOR_CLICK_XPATH)


