class AddObjectModal(ConfirmationModal):
    _OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH = '//div[@class="modal-body"]//div[@class="choose-class-row"]//button'
    _CHOOSE_OBJECT_CLASS_ITEM_XPATH = '//div[@class="modal-body"]//div[@class="choose-class-row"]//li//span'

    _PLAN_FROM_ROW_DROPDOWN_BUTTON_XPATH = '//div[@class="modal-body"]//div[@class="copy-from-row"][1]//button'
    _CHOOSE_PLAN_ITEM_ITEM_XPATH = '//div[@class="modal-body"]//div[@class="copy-from-row"][1]//li//span'

    _COPY_FROM_BUTTON_XPATH = '//div[@class="modal-body"]//div[@class="copy-from-row"][2]//button'
    _CHOOSE_COPY_ITEM_XPATH = '//div[@class="modal-body"]//div[@class="copy-from-row"][2]//li//span'
    _INCLUDING_SUBOBJECT = '//div[@class="modal-body"]//div[@class="copy-from-row"][3]//input'

    _ID_INPUT_XPATH = '//div[@class="modal-body"]//div[contains(@class, "id-input-row")]//input'
    _LOAD_DEFAULT_VALUE_XPATH = '//div[@class="modal-body"]//div[@class="load-default-row"]//input'
    _SUBMIT_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Submit"]/button'
    _CANCEL_BUTTON_XPATH = '//div[@class="modal-content"]//ui-button[@a-text="Cancel"]/button'

    def wait_until_add_object_modal_appear(self, timeout=60):
        self.wait_until_modal_appear((By.XPATH, self._MODAL_XPATH), timeout)

    def add_object(self, object_class_name, plan_to_copy_from=None, copy_from=None, include_subobject=False,
                   id_value=None, is_load_default_values=False, timeout=60):
        self.select_element_from_dropdown_list_by_text_and_click(
            object_class_name,
            (By.XPATH, self._OBJECT_CLASS_ROW_DROPDOWN_BUTTON_XPATH),
            (By.XPATH, self._CHOOSE_OBJECT_CLASS_ITEM_XPATH),
            timeout
        )

        if plan_to_copy_from:
            self.select_element_from_dropdown_list_by_text_and_click(
                plan_to_copy_from,
                (By.XPATH, self._PLAN_FROM_ROW_DROPDOWN_BUTTON_XPATH),
                (By.XPATH, self._CHOOSE_PLAN_ITEM_ITEM_XPATH),
                timeout
            )

        if copy_from:
            self.select_element_from_dropdown_list_by_text_and_click(
                copy_from,
                (By.XPATH, self._COPY_FROM_BUTTON_XPATH),
                (By.XPATH, self._CHOOSE_COPY_ITEM_XPATH),
                timeout
            )

        if include_subobject:
            self.select_radiobox_by_xpath(self._INCLUDING_SUBOBJECT, timeout)

        if id_value:
            self.insert_text_to_enable_element((By.XPATH, self._ID_INPUT_XPATH), id_value, timeout)

        if is_load_default_values:
            self.select_radiobox_by_xpath(self._LOAD_DEFAULT_VALUE_XPATH, timeout)

    def submit(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._SUBMIT_BUTTON_XPATH), timeout)


